    23	    public void initialize() {
    24	        try (Connection conn = getConnection();
    25	             Statement stmt = conn.createStatement()) {
    26	
    27	            stmt.execute("""
    28	                CREATE TABLE IF NOT EXISTS rooms (
    29	                    number INTEGER PRIMARY KEY,
    30	                    type VARCHAR(20) NOT NULL
    31	                )
    32	            """);
    33	
    34	            stmt.execute("""
    35	                CREATE TABLE IF NOT EXISTS reservations (
    36	                    id SERIAL PRIMARY KEY,
    37	                    room_number INTEGER NOT NULL,
    38	                    guest_name VARCHAR(255) NOT NULL,
    39	                    guest_email VARCHAR(255) NOT NULL,
    40	                    guest_cpf VARCHAR(11) NOT NULL,
    41	                    check_in DATE NOT NULL,
    42	                    check_out DATE NOT NULL,
    43	                    guests INTEGER NOT NULL,
    44	                    rate_plan VARCHAR(20) NOT NULL,
    45	                    nights INTEGER NOT NULL,
    46	                    subtotal DECIMAL(10, 2) NOT NULL,
    47	                    discount DECIMAL(10, 2) NOT NULL,
    48	                    total DECIMAL(10, 2) NOT NULL,
    49	                    status VARCHAR(20) NOT NULL,
    50	                    amount_paid DECIMAL(10, 2) NOT NULL DEFAULT 0,
    51	                    refund DECIMAL(10, 2)
    52	                )
    53	            """);
    54	
    55	            stmt.execute("""
    56	                CREATE TABLE IF NOT EXISTS messages (
    57	                    id SERIAL PRIMARY KEY,
    58	                    channel VARCHAR(20) NOT NULL,
    59	                    recipient VARCHAR(255) NOT NULL,
    60	                    subject VARCHAR(500) NOT NULL,
    61	                    body TEXT NOT NULL
    62	                )
    63	            """);
    64	
    65	            initializeRooms();
    66	
    67	        } catch (SQLException e) {
    68	            throw new RuntimeException("Failed to initialize database", e);
    69	        }
    70	    }
