    17	    public ReservationController(ReservationService reservationService) {
    18	        this.reservationService = reservationService;
    19	    }
    20	
    21	    public void createReservation(Context ctx) {
    22	        Map<String, Object> body = ctx.bodyAsClass(Map.class);
    23	
    24	        try {
    25	            Integer roomNumber = getRequiredInteger(body, "roomNumber");
    26	            String guestName = getRequiredString(body, "guestName");
    27	            String guestEmail = getRequiredString(body, "guestEmail");
    28	            String guestCpf = getRequiredString(body, "guestCpf");
    29	            LocalDate checkIn = getRequiredDate(body, "checkIn");
    30	            LocalDate checkOut = getRequiredDate(body, "checkOut");
    31	            Integer guests = getRequiredInteger(body, "guests");
    32	            RatePlan ratePlan = getRequiredEnum(body, "ratePlan", RatePlan.class);
    33	
    34	            Reservation reservation = reservationService.createReservation(
    35	                roomNumber, guestName, guestEmail, guestCpf,
    36	                checkIn, checkOut, guests, ratePlan
    37	            );
    38	
    39	            ctx.status(201).json(toReservationMap(reservation));
    40	
    41	        } catch (IllegalArgumentException e) {
    42	            throw ApiException.invalidRequest(e.getMessage());
    43	        }
    44	    }
