    28	    public Reservation createReservation(int roomNumber, String guestName, String guestEmail,
    29	                                       String guestCpf, LocalDate checkIn, LocalDate checkOut,
    30	                                       int guests, RatePlan ratePlan) {
    31	
    32	        Room room = roomService.getRoomByNumber(roomNumber);
    33	
    34	        if (guests < 1) {
    35	            throw ApiException.invalidRequest("Number of guests must be at least 1");
    36	        }
    37	
    38	        if (guests > room.getCapacity()) {
    39	            throw ApiException.capacityExceeded();
    40	        }
    41	
    42	        if (!checkOut.isAfter(checkIn)) {
    43	            throw ApiException.invalidRequest("Check-out date must be after check-in date");
    44	        }
    45	
    46	        List<Reservation> conflicts = reservationRepository.findConflicting(roomNumber, checkIn, checkOut, null);
    47	        if (!conflicts.isEmpty()) {
    48	            throw ApiException.roomUnavailable();
    49	        }
    50	
    51	        Reservation reservation = new Reservation();
    52	        reservation.setRoomNumber(roomNumber);
    53	        reservation.setGuestName(guestName);
    54	        reservation.setGuestEmail(guestEmail);
    55	        reservation.setGuestCpf(guestCpf);
    56	        reservation.setCheckIn(checkIn);
    57	        reservation.setCheckOut(checkOut);
    58	        reservation.setGuests(guests);
    59	        reservation.setRatePlan(ratePlan);
    60	
    61	        calculatePricing(reservation, room);
    62	
    63	        return reservationRepository.save(reservation);
    64	    }
    65	
    66	    private void calculatePricing(Reservation reservation, Room room) {
    67	        int nights = (int) ChronoUnit.DAYS.between(reservation.getCheckIn(), reservation.getCheckOut());
    68	        reservation.setNights(nights);
    69	
    70	        BigDecimal subtotal = BigDecimal.ZERO;
    71	        LocalDate currentDate = reservation.getCheckIn();
    72	
    73	        for (int i = 0; i < nights; i++) {
    74	            double baseRate = room.getNightlyRate();
    75	            if (DateUtil.isHighSeason(currentDate)) {
    76	                baseRate = baseRate * 1.20;
    77	            }
    78	            BigDecimal nightRate = MoneyUtil.round(baseRate);
    79	            subtotal = subtotal.add(nightRate);
    80	            currentDate = currentDate.plusDays(1);
    81	        }
    82	
    83	        subtotal = MoneyUtil.round(subtotal);
    84	        reservation.setSubtotal(subtotal);
    85	
    86	        BigDecimal discount = BigDecimal.ZERO;
    87	        if (reservation.getRatePlan().getDiscount() > 0) {
    88	            discount = subtotal.multiply(BigDecimal.valueOf(reservation.getRatePlan().getDiscount()));
    89	            discount = MoneyUtil.round(discount);
    90	        }
    91	        reservation.setDiscount(discount);
    92	
    93	        BigDecimal total = subtotal.subtract(discount);
    94	        total = MoneyUtil.round(total);
    95	        reservation.setTotal(total);
    96	    }
